1846:     fn ensure_job_input_ownership(&self, job_id: &str) -> RuntimeResult<()> {
1847:         let plan = self.registry.execution_plan(job_id)?;
1848:         if plan.effective_inputs.is_empty() {
1849:             if plan.input_set_id.is_some() {
1850:                 return Err(RuntimeError::new(
1851:                     RuntimeErrorCode::RegistryCorrupt,
1852:                     "inputSetId exists without effective immutable inputs",
1853:                     Some("executionPlan"),
1854:                     false,
1855:                 ));
1856:             }
1857:             return Ok(());
1858:         }
1859:         if plan.input_set_id.is_none() {
1860:             return Err(RuntimeError::new(
1861:                 RuntimeErrorCode::RegistryCorrupt,
1862:                 "effective immutable inputs have no committed inputSetId",
1863:                 Some("executionPlan"),
1864:                 false,
1865:             ));
1866:         }
1867:         let requests = effective_input_requests_from_plan(&plan)?;
1868:         let owned_root = self.executor.job_input_path(job_id);
1869:         let prepared_root = self.executor.input_materializations_root().join(job_id);
1870:         fs::create_dir_all(self.executor.job_inputs_root())
1871:             .map_err(|error| io_error("create Job input ownership root", error))?;
1872:         if owned_root.exists() {
1873:             verify_effective_input_set(&owned_root, &requests)?;
1874:             if prepared_root.exists() {
1875:                 self.discard_prepared_input_set(&prepared_root)?;
1876:             }
1877:             return Ok(());
1878:         }
1879:         if !prepared_root.exists() {

1880:             return Err(RuntimeError::new(
1881:                 RuntimeErrorCode::ReconciliationRequired,
1882:                 "committed Job immutable inputs are missing both prepared and Job-owned bytes",
1883:                 Some("executionPlan.inputSetId"),
1884:                 true,
1885:             ));
1886:         }
1887:         verify_effective_input_set(&prepared_root, &requests)?;
1888:         match fs::rename(&prepared_root, &owned_root) {
1889:             Ok(()) => sync_directory(&self.executor.job_inputs_root())?,
1890:             Err(error) if owned_root.exists() => {
1891:                 let _ = error;
1892:             }
1893:             Err(error) => return Err(io_error("adopt prepared immutable inputs for Job", error)),
1894:         }
1895:         verify_effective_input_set(&owned_root, &requests)?;
1896:         Ok(())
1897:     }
