1899:     fn ensure_attempt_dispatched(&self, attempt: &AttemptRecord) -> RuntimeResult<()> {
1900:         if let Err(error) = self.verify_committed_execution_provider(&attempt.job_id) {
1901:             if error.code == RuntimeErrorCode::ProviderStateMismatch {
1902:                 self.commit_control_terminal(
1903:                     attempt,
1904:                     AttemptState::Failed,
1905:                     "EXECUTION_PROVIDER_PRECONDITION_DRIFT",
1906:                     Some(error.to_string()),
1907:                 )?;
1908:                 return Ok(());
1909:             }
1910:             return Err(error);
1911:         }
1912:         if let Err(error) = self.verify_committed_host_dependencies(&attempt.job_id) {
1913:             if matches!(
1914:                 error.code,
1915:                 RuntimeErrorCode::WorkspaceStateMismatch | RuntimeErrorCode::InvalidRequest
1916:             ) {
1917:                 self.commit_control_terminal(
1918:                     attempt,
1919:                     AttemptState::Failed,
1920:                     "HOST_DEPENDENCY_PRECONDITION_DRIFT",
1921:                     Some(error.to_string()),
1922:                 )?;
1923:                 return Ok(());
1924:             }
1925:             return Err(error);
1926:         }
1927:         if let Err(error) = self.ensure_job_input_ownership(&attempt.job_id) {
1928:             if matches!(
1929:                 error.code,
1930:                 RuntimeErrorCode::ReconciliationRequired | RuntimeErrorCode::WorkspaceStateMismatch
1931:             ) {
1932:                 self.commit_control_terminal(
1933:                     attempt,
1934:                     AttemptState::Failed,
1935:                     "INPUT_PRECONDITION_DRIFT",
1936:                     Some(error.to_string()),
1937:                 )?;
1938:                 return Ok(());
1939:             }
1940:             return Err(error);
1941:         }
1942:         let mut attempt = attempt.clone();
1943:         if attempt.bundle_digest.is_none() {
1944:             attempt = match self.materialize_bundle(&attempt) {
1945:                 Ok(current) => current,
1946:                 Err(error) if error.code == RuntimeErrorCode::AttemptStateConflict => {
1947:                     let current = self.registry.get_attempt(&attempt.attempt_id)?;
1948:                     if current.bundle_digest.is_none() && current.state == AttemptState::Accepted {
1949:                         self.materialize_bundle(&current)?
1950:                     } else {
1951:                         current
1952:                     }
1953:                 }
1954:                 Err(error) => return Err(error),
1955:             };
1956:         }
1957:         match attempt.state {
1958:             AttemptState::Accepted => match self.dispatch_attempt(&attempt) {
1959:                 Ok(()) => Ok(()),
1960:                 Err(error) if error.code == RuntimeErrorCode::AttemptStateConflict => {
1961:                     let current = self.registry.get_attempt(&attempt.attempt_id)?;
1962:                     match current.state {
1963:                         AttemptState::Starting
1964:                         | AttemptState::Running
1965:                         | AttemptState::Stopping
1966:                         | AttemptState::Recovering => self.reconcile_attempt(&current.attempt_id),
1967:                         state if state.is_terminal() => Ok(()),
1968:                         _ => Err(error),
1969:                     }
1970:                 }
1971:                 Err(error) => Err(error),
1972:             },
1973:             AttemptState::Starting
1974:             | AttemptState::Running
1975:             | AttemptState::Stopping
1976:             | AttemptState::Recovering => {
1977:                 self.reconcile_attempt(&attempt.attempt_id)?;
1978:                 Ok(())
1979:             }
1980:             _ => Ok(()),
1981:         }
1982:     }
