349: pub(crate) fn build_windows_systemd_run_command(
350:     spec: &WindowsSystemdRunSpec<'_>,
351: ) -> RuntimeResult<Command> {
352:     spec.config.validate()?;
353:     let launcher = fs::canonicalize(&spec.config.launcher_path).map_err(|error| {
354:         RuntimeError::new(
355:             RuntimeErrorCode::IoError,
356:             format!("canonicalize Windows launcher: {error}"),
357:             Some("windows.launcherPath"),
358:             false,
359:         )
360:     })?;
361:     let executable = mounted_windows_path(spec.executable).ok_or_else(|| {
362:         RuntimeError::invalid(
363:             "windows_native executable must reside on a WSL-mounted Windows drive",
364:             "execution.executable",
365:         )
366:     })?;
367:     let cwd = windows_visible_path(spec.config, spec.cwd, "execution.cwdRelative")?;
368:     let bundle = windows_visible_path(spec.config, spec.bundle_path, "bundlePath")?;
369:     let job_name = format!("Ordivon.{}", spec.attempt_id);
370: 
371:     let mut command = Command::new("systemd-run");
372:     command
373:         .arg(format!("--unit={}", spec.unit_name))
374:         .arg("--no-block")
375:         // Agent-authored argv is execution truth. systemd-run otherwise expands $VAR and
376:         // ${VAR} from the manager environment before the Windows launcher receives it.
377:         .arg("--expand-environment=no")
378:         .args([
379:             "--property=Type=exec",
380:             "--property=CollectMode=inactive",
381:             "--property=KillMode=control-group",
382:             "--property=TimeoutStopSec=2s",
383:             "--property=SendSIGKILL=yes",
384:             "--property=StandardOutput=journal",
385:             "--property=StandardError=journal",
386:         ])
387:         .arg(format!(
388:             "--property=RuntimeMaxSec={}ms",
389:             spec.runtime_ceiling_ms
390:         ))
391:         .arg(launcher)
392:         .arg("--runtime-bundle")
393:         .arg(bundle)
394:         .arg("--runtime-job-id")
395:         .arg(spec.job_id)
396:         .arg("--runtime-attempt-id")
397:         .arg(spec.attempt_id)
398:         .arg("--runtime-launch-token-digest")
399:         .arg(spec.launch_token_digest)
400:         .arg("--job-name")
401:         .arg(job_name)
402:         .arg("--authority")
403:         .arg(spec.authority.as_str())
404:         .arg("--timeout-ms")
405:         .arg(spec.timeout_ms.to_string())
406:         .arg("--stdout-limit-bytes")
407:         .arg(spec.stdout_limit_bytes.to_string())
408:         .arg("--stderr-limit-bytes")
409:         .arg(spec.stderr_limit_bytes.to_string())
410:         .arg("--executable")
411:         .arg(executable)
412:         .arg("--cwd")
413:         .arg(cwd)
414:         .arg("--inherit-environment")
415:         .arg("false");
416: 
417:     for (name, value) in spec.environment {
418:         command.arg("--env").arg(format!("{name}={value}"));
419:     }
420:     if let Some(value) = spec.budget.memory_max_bytes {
421:         command.arg("--memory-max-bytes").arg(value.to_string());
422:     }
423:     if let Some(value) = spec.budget.tasks_max {
424:         command.arg("--active-process-limit").arg(value.to_string());
425:     }
426:     if let Some(value) = spec.budget.cpu_quota_percent {
427:         command.arg("--cpu-quota-percent").arg(value.to_string());
428:     }
429:     command.arg("--").args(spec.args);
430:     Ok(command)
431: }
