433: pub(crate) fn windows_visible_path(
434:     config: &WindowsExecutionConfig,
435:     path: &Path,
436:     field: &str,
437: ) -> RuntimeResult<String> {
438:     if let Some(path) = mounted_windows_path(path) {
439:         return Ok(path);
440:     }
441:     if !path.is_absolute() {
442:         return Err(RuntimeError::invalid(
443:             "Windows-visible path source must be absolute",
444:             field,
445:         ));
446:     }
447:     let text = path
448:         .to_str()
449:         .ok_or_else(|| RuntimeError::invalid("Windows-visible path must be UTF-8", field))?;
450:     let relative = text.trim_start_matches('/').replace('/', "\\");
451:     Ok(format!(
452:         "\\\\wsl.localhost\\{}\\{}",
453:         config.wsl_distribution, relative
454:     ))
455: }
456: 
457: pub(crate) fn mounted_windows_path(path: &Path) -> Option<String> {
458:     let text = path.to_str()?;
459:     let remainder = text.strip_prefix("/mnt/")?;
460:     let bytes = remainder.as_bytes();
461:     if bytes.len() < 2 || !bytes[0].is_ascii_alphabetic() || bytes[1] != b'/' {
462:         return None;
463:     }
464:     let drive = (bytes[0] as char).to_ascii_uppercase();
465:     let tail = remainder[2..].replace('/', "\\");
466:     if tail.is_empty() {
467:         Some(format!("{drive}:\\"))
468:     } else {
469:         Some(format!("{drive}:\\{tail}"))
470:     }
471: }
